CREATE TABLE "ingredients" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "aisle" TEXT NOT NULL, "default_unit" TEXT NOT NULL, "avg_piece_weight_g" REAL NULL, "pantry" INTEGER NOT NULL DEFAULT 0 CHECK ("pantry" IN (0, 1)), "perishable" INTEGER NOT NULL DEFAULT 0 CHECK ("perishable" IN (0, 1)), "markers" TEXT NOT NULL DEFAULT '', "allergens" TEXT NOT NULL DEFAULT '', "season_months" TEXT NOT NULL DEFAULT '', "origin" TEXT NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "recipes" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "slug" TEXT NULL UNIQUE, "title" TEXT NOT NULL, "description" TEXT NOT NULL DEFAULT '', "type" TEXT NOT NULL, "servings" INTEGER NOT NULL, "prep_min" INTEGER NOT NULL, "cook_min" INTEGER NOT NULL, "difficulty" TEXT NOT NULL, "equipment" TEXT NOT NULL DEFAULT '', "main_base" TEXT NOT NULL, "origin" TEXT NOT NULL, "seed_version" INTEGER NULL, "photo_path" TEXT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL);
CREATE TABLE "recipe_ingredients" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "recipe_id" INTEGER NOT NULL REFERENCES recipes (id) ON DELETE CASCADE, "ingredient_id" TEXT NOT NULL REFERENCES ingredients (id), "qty" REAL NOT NULL, "unit" TEXT NOT NULL, "optional" INTEGER NOT NULL DEFAULT 0 CHECK ("optional" IN (0, 1)), "note" TEXT NULL, "position" INTEGER NOT NULL);
CREATE TABLE "recipe_steps" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "recipe_id" INTEGER NOT NULL REFERENCES recipes (id) ON DELETE CASCADE, "position" INTEGER NOT NULL, "body" TEXT NOT NULL);
CREATE TABLE "recipe_user_state" ("recipe_id" INTEGER NOT NULL REFERENCES recipes (id) ON DELETE CASCADE, "favorite" INTEGER NOT NULL DEFAULT 0 CHECK ("favorite" IN (0, 1)), "to_place" INTEGER NOT NULL DEFAULT 0 CHECK ("to_place" IN (0, 1)), "disliked" INTEGER NOT NULL DEFAULT 0 CHECK ("disliked" IN (0, 1)), "last_planned_at" INTEGER NULL, PRIMARY KEY ("recipe_id"));
CREATE TABLE "profile" ("id" INTEGER NOT NULL, "onboarded" INTEGER NOT NULL DEFAULT 0 CHECK ("onboarded" IN (0, 1)), "people" INTEGER NOT NULL DEFAULT 2, "diet" TEXT NOT NULL DEFAULT 'omnivore', "no_pork" INTEGER NOT NULL DEFAULT 0 CHECK ("no_pork" IN (0, 1)), "max_min_weekday" INTEGER NOT NULL DEFAULT 30, "max_min_weekend" INTEGER NOT NULL DEFAULT 60, "week_start_day" INTEGER NOT NULL DEFAULT 1, "favorite_share" REAL NOT NULL DEFAULT 0.4, "anti_repeat_weeks" INTEGER NOT NULL DEFAULT 2, "aisle_order" TEXT NOT NULL DEFAULT '', "theme_mode" TEXT NOT NULL DEFAULT 'system', PRIMARY KEY ("id"));
CREATE TABLE "profile_aversions" ("ingredient_id" TEXT NOT NULL REFERENCES ingredients (id), PRIMARY KEY ("ingredient_id"));
CREATE TABLE "profile_exclusions" ("allergen" TEXT NOT NULL, PRIMARY KEY ("allergen"));
CREATE TABLE "profile_equipment" ("equipment" TEXT NOT NULL, PRIMARY KEY ("equipment"));
CREATE TABLE "profile_slots" ("day" INTEGER NOT NULL, "meal" TEXT NOT NULL, PRIMARY KEY ("day", "meal"));
CREATE TABLE "week_menus" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "start_date" INTEGER NOT NULL UNIQUE, "status" TEXT NOT NULL DEFAULT 'draft', "seed" INTEGER NOT NULL DEFAULT 0);
CREATE TABLE "menu_slots" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "menu_id" INTEGER NOT NULL REFERENCES week_menus (id) ON DELETE CASCADE, "day" INTEGER NOT NULL, "meal" TEXT NOT NULL, "kind" TEXT NOT NULL, "recipe_id" INTEGER NULL REFERENCES recipes (id), "servings" INTEGER NOT NULL, "locked" INTEGER NOT NULL DEFAULT 0 CHECK ("locked" IN (0, 1)), "leftovers_from" TEXT NULL, UNIQUE ("menu_id", "day", "meal"));
CREATE TABLE "week_extras" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "menu_id" INTEGER NOT NULL REFERENCES week_menus (id) ON DELETE CASCADE, "recipe_id" INTEGER NOT NULL REFERENCES recipes (id), "servings" INTEGER NOT NULL);
CREATE TABLE "shopping_items" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "menu_id" INTEGER NOT NULL REFERENCES week_menus (id) ON DELETE CASCADE, "ingredient_id" TEXT NULL REFERENCES ingredients (id), "label" TEXT NULL, "quantity" REAL NULL, "unit" TEXT NULL, "bought" INTEGER NOT NULL DEFAULT 0 CHECK ("bought" IN (0, 1)), "at_home" INTEGER NOT NULL DEFAULT 0 CHECK ("at_home" IN (0, 1)), "manual" INTEGER NOT NULL DEFAULT 0 CHECK ("manual" IN (0, 1)));
CREATE TABLE "app_meta" ("key" TEXT NOT NULL, "value" TEXT NOT NULL, PRIMARY KEY ("key"));
